rules.script:
if active("IO61", "gpio_out") || option("IO61", "pull") == "down" {
    warn("IO61 is a strapping pin (boot mode: 1 (default, weak pull-up) boots from SPI flash; 0 with IO60 high enters joint download; both low is invalid); keep its level valid during reset", ["IO61"])
} else {
    ok()
}

if active("IO60", "gpio_out") || option("IO60", "pull") == "down" {
    warn("IO60 is a strapping pin (boot mode with IO61 and UART0 ROM messages; weak pull-up, default 1); keep its level valid during reset", ["IO60"])
} else {
    ok()
}

if function("IO36") != "gpio_in" || option("IO36", "pull") == "down" {
    warn("IO36 is a strapping pin pulled up in the module: high selects 3.3 V for VDD_SPI when EFUSE_PMU_FLASH_POWER_SEL is 0; keep it high at reset", ["IO36"])
} else {
    ok()
}

if function("IO37") != "gpio_in" {
    warn("IO37 is a strapping pin without a pull: with EFUSE_JTAG_SEL_ENABLE set it selects the JTAG source (1 USB Serial/JTAG, 0 JTAG pins); drive it to a defined level at reset", ["IO37"])
} else {
    ok()
}

if !active("IO54", "jtag_mtdo") || !active("IO55", "jtag_mtck") || !active("IO56", "jtag_mtdi") || !active("IO57", "jtag_mtms") {
    warn("IO54 to IO57 are the JTAG pins by default; using them otherwise leaves only USB Serial/JTAG for debugging", ["IO54", "IO55", "IO56", "IO57"])
} else {
    ok()
}

if !active("IO33", "usb_serial_jtag_dm") || !active("IO34", "usb_serial_jtag_dp") {
    warn("IO33 and IO34 are USB Serial/JTAG by default; firmware must reconfigure them before GPIO use, and USB debugging is lost", ["IO33", "IO34"])
} else {
    ok()
}

if !active("TX0", "uart0_txd") || !active("RX0", "uart0_rxd") {
    warn("TX0 and RX0 are UART0, used by the ROM for messages and download", ["TX0", "RX0"])
} else {
    ok()
}

if used("LP_I2C") && (role("LP_UART", "dtrn") || role("LP_UART", "dsrn") || role("LP_UART", "rtsn") || role("LP_UART", "ctsn")) {
    forbid("LP UART flow control and LP I2C cannot be used at the same time", ["IO2", "IO3", "IO4", "IO5", "IO6", "IO7"])
} else {
    ok()
}

if active("IO61", "gpio_out") || option("IO61", "pull") == "down" {
    warn("IO61 is a strapping pin (boot mode: 1 (default, weak pull-up) boots from SPI flash; 0 with IO60 high enters joint download; both low is invalid); keep its level valid during reset", ["IO61"])
} else {
    ok()
}

if active("IO60", "gpio_out") || option("IO60", "pull") == "down" {
    warn("IO60 is a strapping pin (boot mode with IO61 and UART0 ROM messages; weak pull-up, default 1); keep its level valid during reset", ["IO60"])
} else {
    ok()
}

if function("IO36") != "gpio_in" || option("IO36", "pull") == "down" {
    warn("IO36 is a strapping pin pulled up in the module: high selects 3.3 V for VDD_SPI when EFUSE_PMU_FLASH_POWER_SEL is 0; keep it high at reset", ["IO36"])
} else {
    ok()
}

if function("IO37") != "gpio_in" {
    warn("IO37 is a strapping pin without a pull: with EFUSE_JTAG_SEL_ENABLE set it selects the JTAG source (1 USB Serial/JTAG, 0 JTAG pins); drive it to a defined level at reset", ["IO37"])
} else {
    ok()
}

if !active("IO54", "jtag_mtdo") || !active("IO55", "jtag_mtck") || !active("IO56", "jtag_mtdi") || !active("IO57", "jtag_mtms") {
    warn("IO54 to IO57 are the JTAG pins by default; using them otherwise leaves only USB Serial/JTAG for debugging", ["IO54", "IO55", "IO56", "IO57"])
} else {
    ok()
}

if !active("IO33", "usb_serial_jtag_dm") || !active("IO34", "usb_serial_jtag_dp") {
    warn("IO33 and IO34 are USB Serial/JTAG by default; firmware must reconfigure them before GPIO use, and USB debugging is lost", ["IO33", "IO34"])
} else {
    ok()
}

if !active("TX0", "uart0_txd") || !active("RX0", "uart0_rxd") {
    warn("TX0 and RX0 are UART0, used by the ROM for messages and download", ["TX0", "RX0"])
} else {
    ok()
}

if used("LP_I2C") && (role("LP_UART", "dtrn") || role("LP_UART", "dsrn") || role("LP_UART", "rtsn") || role("LP_UART", "ctsn")) {
    forbid("LP UART flow control and LP I2C cannot be used at the same time", ["IO2", "IO3", "IO4", "IO5", "IO6", "IO7"])
} else {
    ok()
}
